select id, role_name, role_code, description, is_enabled, create_time
from blog_role
where deleted_at = 0

    and role_name like concat('%', #{roleName}, '%')


    and role_code = #{roleCode}


    and is_enabled = #{isEnabled}

order by update_time desc
limit #{offset}, #{size}

select count(*)
from blog_role
where deleted_at = 0

    and role_name like concat('%', #{roleName}, '%')


    and role_code = #{roleCode}


    and is_enabled = #{isEnabled}

select id, role_name, role_code, description, is_enabled, create_time
from blog_role
where deleted_at = 0
  and role_code = #{roleCode}

    and id != #{excludeId}
